'use strict';
let warehousePage=1,warehousePageSize=20,warehouseStatus='all',warehouseReturnY=0,warehouseEditing=false,partQuery='',partStatus='all';
function warehouseFiltered(){return state.projects.filter(p=>{const found=(p.name+' '+projectDate(p)+' '+(p.location||'')).toLowerCase().includes(query.trim().toLowerCase()),has=p.parts.length>0,ready=has&&p.parts.every(i=>preparedQuantity(p,i)>=totalNeed(i));return found&&(warehouseStatus==='all'||warehouseStatus==='ready'&&ready||warehouseStatus==='waiting'&&has&&!ready||warehouseStatus==='stock'&&totalStock(p)>0);});}
rows=function(){const list=warehouseFiltered(),pages=Math.max(1,Math.ceil(list.length/warehousePageSize));warehousePage=Math.min(warehousePage,pages);return list.slice((warehousePage-1)*warehousePageSize,warehousePage*warehousePageSize).map(p=>{const ready=p.parts.filter(i=>preparedQuantity(p,i)>=totalNeed(i)).length;return '<article class="project"><button class="project-row" data-project="'+esc(p.id)+'"><span class="project-name"><strong>'+esc(p.name)+'</strong></span><span>'+esc(projectDate(p))+'</span><span>'+(p.basketCount??1)+'</span><span>'+(p.parts.length?ready+'／'+p.parts.length+' 項':'尚無零件')+'</span><span>'+esc(p.location||'未填寫')+'</span><span>'+totalStock(p)+' 件</span></button></article>';}).join('')+(list.length?'':'<p class="empty">沒有符合條件的專案</p>')+(project()?'<div class="warehouse-detail-staging">'+expanded(project())+'</div>':'');};
function warehouseDirty(){const p=project(),form=$('#receipt-form');if(!p||!form||(!canDo('warehouse.stock')&&!canDo('warehouse.manage')))return false;const fd=new FormData(form);return p.parts.some(i=>partChanged(i,fd))||String(fd.get('basketCount')??p.basketCount)!==String(p.basketCount??1)||canDo('warehouse.manage')&&locationFromForm(fd)!==(p.location||'A櫃 1層');}
function partChanged(i,fd){return Number(fd.get('q:'+i.id))!==0||Number(fd.get('out:'+i.id))!==0||['name','spec','need','sets'].some(k=>String(fd.get(k+':'+i.id)??i[k]??'')!==String(i[k]??(k==='sets'?1:'')));}
async function closeWarehouseDetail(){if(cloudBusy||failedCandidate){toast('請先完成儲存或處理頁面上方提示');return;}if(warehouseDirty()&&!await confirmAction('尚有未儲存內容。關閉後會暫存於本頁面，重新整理或離開網站仍會遺失。確定關閉？'))return;captureDraft();selectedId='';$('#warehouse-dialog')?.remove();render();window.scrollTo(0,warehouseReturnY);}
function enhanceWarehouseList(){const box=$('#projects');if(!box)return;const workspace=box.closest('.workspace');workspace.classList.add('warehouse-compact');workspace.querySelector('.column-head').innerHTML=['案名','建立日期','籃數','已收齊','庫房位置','現有庫存'].map(x=>'<span>'+x+'</span>').join('');document.querySelectorAll('.project-order-controls').forEach(x=>x.remove());
 const tools=document.createElement('div');tools.className='warehouse-list-tools';tools.innerHTML='<label>篩選 <select id="warehouse-status">'+[['all','全部'],['waiting','尚未收齊'],['ready','已收齊'],['stock','有庫存']].map(([v,l])=>'<option value="'+v+'" '+(v===warehouseStatus?'selected':'')+'>'+l+'</option>').join('')+'</select></label><label>每頁 <select id="warehouse-size">'+[20,50,100].map(v=>'<option '+(v===warehousePageSize?'selected':'')+'>'+v+'</option>').join('')+'</select> 筆</label>'+(canDo('warehouse.manage')?'<button id="warehouse-sort" type="button">調整排序</button>':'');workspace.querySelector('.toolbar').after(tools);
 const pager=document.createElement('div');pager.className='warehouse-pager';const count=warehouseFiltered().length,pages=Math.max(1,Math.ceil(count/warehousePageSize));pager.innerHTML='<span>共 '+count+' 案 · 第 '+warehousePage+'／'+pages+' 頁</span><button type="button" id="warehouse-prev" '+(warehousePage===1?'disabled':'')+'>上一頁</button><button type="button" id="warehouse-next" '+(warehousePage===pages?'disabled':'')+'>下一頁</button>';workspace.append(pager);
 $('#warehouse-status').onchange=e=>{warehouseStatus=e.target.value;warehousePage=1;render();};$('#warehouse-size').onchange=e=>{warehousePageSize=Number(e.target.value);warehousePage=1;render();};$('#warehouse-prev').onclick=()=>{warehousePage--;render();};$('#warehouse-next').onclick=()=>{warehousePage++;render();};$('#search').oninput=e=>{query=e.target.value;warehousePage=1;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};
 $('#warehouse-sort')?.addEventListener('click',()=>numberedOrderDialog('庫房 · 調整排序',state.projects.map(p=>({id:p.id,label:p.name})),async ids=>{const map=new Map(state.projects.map(p=>[p.id,p]));state.projects=ids.map(id=>map.get(id));addAudit('調整排序','庫房專案完整清單','庫房管理');await saveCloud(state);if(failedCandidate)throw Error('尚未儲存成功');render();}));
 document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{warehouseReturnY=window.scrollY;selectedId=b.dataset.project;warehouseEditing=false;partQuery='';partStatus='all';render();});
}
function enhanceWarehouseDetail(){const detail=$('.project-detail'),p=project();if(!detail||!p)return;const dialog=document.createElement('dialog');dialog.id='warehouse-dialog';dialog.innerHTML='<div class="warehouse-dialog-head"><h2>'+esc(p.name)+'</h2><button type="button" id="warehouse-close">關閉</button></div>';document.body.append(dialog);dialog.append(detail);$('.warehouse-detail-staging')?.remove();dialog.showModal();$('#warehouse-close').onclick=closeWarehouseDetail;dialog.addEventListener('cancel',e=>{e.preventDefault();closeWarehouseDetail();});
 const title=detail.querySelector('.detail-title'),deleteButton=$('#delete-project');if(deleteButton){const more=document.createElement('details');more.className='warehouse-more';more.innerHTML='<summary>更多操作</summary>';more.append(deleteButton);title.append(more);}
 const form=$('#receipt-form');if(!form)return;const tools=document.createElement('div');tools.className='warehouse-list-tools';tools.innerHTML='<input id="part-search" placeholder="搜尋零件名稱或規格" value="'+esc(partQuery)+'"><select id="part-status" aria-label="零件篩選">'+[['all','全部'],['waiting','尚未收齊'],['stock','有庫存'],['changed','本次有填寫']].map(([v,l])=>'<option value="'+v+'" '+(v===partStatus?'selected':'')+'>'+l+'</option>').join('')+'</select>'+(canDo('warehouse.manage')?'<button type="button" id="part-edit-mode">'+(warehouseEditing?'完成編輯':'編輯零件資料')+'</button>':'');form.querySelector('.storage-fields').after(tools);
 const inputs=[...form.querySelectorAll('.name-input,.spec-input,.demand-input,.sets-input')];for(const input of inputs){const text=document.createElement('span');text.className='part-read-value';text.textContent=input.value;input.after(text);input.classList.add('part-edit-value');if(!canDo('warehouse.manage'))input.readOnly=true;}
 const mode=()=>{detail.classList.toggle('warehouse-editing',warehouseEditing&&canDo('warehouse.manage'));form.querySelectorAll('[data-remove]').forEach(b=>b.hidden=!warehouseEditing||!canDo('warehouse.manage'));};mode();$('#part-edit-mode')?.addEventListener('click',()=>{warehouseEditing=!warehouseEditing;$('#part-edit-mode').textContent=warehouseEditing?'完成編輯':'編輯零件資料';mode();});
 const note=document.createElement('div');note.className='warehouse-change-summary';form.querySelector('.receipt-controls').prepend(note);
 function update(){const fd=new FormData(form);let changed=0,hiddenChanged=0;for(const row of form.querySelectorAll('tr[data-item]')){const i=p.parts.find(i=>i.id===row.dataset.item),has=partChanged(i,fd),name=String(fd.get('name:'+i.id)),spec=String(fd.get('spec:'+i.id));const visible=(name+' '+spec).toLowerCase().includes(partQuery.toLowerCase())&&(partStatus==='all'||partStatus==='changed'&&has||partStatus==='waiting'&&preparedQuantity(p,i)<Number(fd.get('need:'+i.id))*Number(fd.get('sets:'+i.id))||partStatus==='stock'&&inStock(p,i.id)>0);row.hidden=!visible;row.classList.toggle('part-changed',has);if(has){changed++;if(!visible)hiddenChanged++;}row.querySelectorAll('.part-edit-value').forEach(x=>x.nextElementSibling.textContent=x.value);}note.innerHTML='<strong>本次修改 '+changed+' 項</strong>'+(hiddenChanged?'<span>另有 '+hiddenChanged+' 項已填寫但未顯示</span><button type="button" id="show-part-changes">查看本次修改</button>':'');$('#show-part-changes')?.addEventListener('click',()=>{partQuery='';partStatus='changed';$('#part-search').value='';$('#part-status').value='changed';update();});}
 $('#part-search').oninput=e=>{partQuery=e.target.value;update();};$('#part-status').onchange=e=>{partStatus=e.target.value;update();};form.addEventListener('input',update);update();
}
const renderBeforeWarehouseView=render;render=function(){const old=$('#warehouse-dialog');if(old)old.remove();renderBeforeWarehouseView();if(activeManagementPage().id==='warehouse'){enhanceWarehouseList();enhanceWarehouseDetail();}};
function warehouseHasDrafts(){return Object.entries(drafts).some(([id,d])=>{const p=state.projects.find(x=>x.id===id);if(!p)return false;const fd={get:k=>d[k]??null};return p.parts.some(i=>partChanged(i,fd))||d.basketCount!=null&&String(d.basketCount)!==String(p.basketCount??1)||d.cabinet!=null&&locationFromForm(fd)!==(p.location||'A櫃 1層');});}
window.addEventListener('beforeunload',e=>{if(warehouseDirty()||warehouseHasDrafts()){e.preventDefault();e.returnValue='';}});
